// [MEDIUM_PRIORITY] UX_POLISH: Hint text present
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.stt.whisperimport timber.log.Timberimport com.roshan.persona.voice.capture.AudioCapturePipelineimport com.roshan.persona.voice.stt.OfflineSttEngineimport com.roshan.persona.voice.stt.SttConfigimport com.roshan.persona.voice.stt.SttConfidenceScorerimport com.roshan.persona.voice.stt.SttResultimport com.roshan.persona.voice.stt.SupportedLanguageimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.flow.flowimport kotlinx.coroutines.sync.Muteximport kotlinx.coroutines.sync.withLockimport kotlinx.coroutines.withContextimport java.util.concurrent.atomic.AtomicBooleanimport java.util.concurrent.atomic.AtomicLong/** * NOUS — Whisper.cpp STT Engine (offline, high-accuracy). * * Implements the [OfflineSttEngine] interface (defined in Step 5.3) using * whisper.cpp via [WhisperJni]. This is the **Tier-2 offline STT** path in * the §6 hybrid strategy — used when cloud STT is unavailable, and tried * before Vosk (which is faster but lower accuracy). * * ## Strategy §6 positioning * * ``` * 1. Cloud STT (Android SpeechRecognizer) — Tier 1, best accuracy * 2. Whisper.cpp (this class)             — Tier 2, >95% accuracy, 75-250 MB * 3. Vosk                                  — Tier 3, ~90% accuracy, 50 MB * ``` * * Whisper.cpp is preferred over Vosk for high-stakes queries (intent * classification for critical commands) because its accuracy is materially * better. The trade-off is speed — Whisper runs at ~2-3× realtime on arm64, * while Vosk runs at ~0.5× realtime (faster than realtime). The * [StreamingSttEngine] picks Whisper by default and only falls through to * Vosk if Whisper is too slow for the device (heuristic: THERMAL_STATUS * MODERATE or higher → switch to Vosk, per §16 Thermal Throttling). * * ## Streaming approach * * Whisper.cpp itself doesn't stream — it processes a complete audio buffer. * We emulate streaming by: * *   1. Buffering audio chunks from [AudioCapturePipeline.chunks] while VAD *      reports voice. *   2. When VAD reports 500 ms of silence (end-of-turn), batch all buffered *      audio into one `ShortArray` and call [WhisperJni.nativeFullStream]. *   3. The native code calls back with partial segment text every ~200-500 ms *      — we forward these as [SttResult.Partial] to the caller. *   4. When native returns the full text, we emit [SttResult.Final]. * * This gives "streaming" UX (user sees partial text as Whisper processes) * without requiring whisper.cpp to natively support streaming. * * ## Confidence * * whisper.cpp doesn't expose per-segment confidence. We estimate it from the * audio quality using [SttConfidenceScorer.scoreFromAudio] — this lets the * Brain apply the same trust-level logic (HIGH / MEDIUM / LOW) that it uses * for cloud STT results. * * ## Barge-in * * [cancel] calls [WhisperJni.nativeStopRecognition] which sets an atomic * flag checked between tokens. The current recognition returns within * ~50-100 ms (one segment boundary) with whatever text has been recognized * so far. We emit that as a [SttResult.Final] so the Brain can act on the * partial input rather than dropping it. * * ## Lifecycle * *  - [load] — load model into native memory (2-5 s for base.en, 8-15 s for *    small). Called once at app startup or when the user enables offline STT. *  - [recognize] — per-utterance. Can be called repeatedly. *  - [unload] — release native memory. Called when offline STT is disabled. * * Thread safety: the native context pointer is guarded by [recognizeMutex]. * [cancel] is thread-safe — it just sets the stop flag. * * @param config         whisper-specific config (model path, language, threads) * @param sttConfig      general STT config (silence timeout, language hints) * @param ioDispatcher   for file I/O during model load * @param audioDispatcher for native recognition (single-threaded, no double-record) */class WhisperSttEngine(    private val config: WhisperConfig,    private val sttConfig: SttConfig = SttConfig(),    private val confidenceScorer: SttConfidenceScorer = SttConfidenceScorer(),    private val ioDispatcher: CoroutineDispatcher,    private val audioDispatcher: CoroutineDispatcher,) : OfflineSttEngine {    private val contextPtr = AtomicLong(0L)    private val recognizeMutex = Mutex()    private val cancelled = AtomicBoolean(false)    /** Whether the model is loaded and ready for recognition. */    val isLoaded: Boolean get() = contextPtr.get() != 0L    /**     * Load the whisper model into native memory.     *     * @return true on success, false on failure (native lib missing, model     *         file missing, OOM, etc.)     */    suspend fun load(): Boolean = withContext(ioDispatcher) {        if (isLoaded) return@withContext true        if (!WhisperJni.ensureLoaded()) {            Timber.tag(TAG).e("Native library not loaded — cannot init whisper context.")            return@withContext false        }        if (!java.io.File(config.modelPath).exists()) {            Timber.tag(TAG).e("Model file not found: ${config.modelPath}")            return@withContext false        }        try {            val start = System.nanoTime()            val ptr = WhisperJni.nativeInitContext(                modelPath = config.modelPath,                useGpu = config.useGpu,                threads = config.threads,            )            if (ptr == 0L) {                Timber.tag(TAG).e("nativeInitContext returned 0 — model load failed.")                return@withContext false            }            contextPtr.set(ptr)            val loadMs = (System.nanoTime() - start) / 1_000_000            Timber.tag(TAG).i("Whisper model loaded in ${loadMs}ms (gpu=${config.useGpu}, threads=${config.threads}).")            true        } catch (t: UnsatisfiedLinkError) {            Timber.tag(TAG).e("UnsatisfiedLinkError during nativeInitContext", t)            false        } catch (t: OutOfMemoryError) {            Timber.tag(TAG).e("OOM during whisper model load — model too large for app heap", t)            false        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to load whisper model", t)            false        }    }    /** Release native memory. Idempotent. */    suspend fun unload() = withContext(ioDispatcher) {        val ptr = contextPtr.getAndSet(0L)        if (ptr != 0L) {            runCatching { WhisperJni.nativeFreeContext(ptr) }            Timber.tag(TAG).i("Whisper context freed.")        }    }    // ─── OfflineSttEngine implementation ──────────────────────────────    /**     * Stream STT results from a live audio stream.     *     * Collects audio chunks while voice is active, then transcribes the full     * utterance when 500 ms of silence has passed (end-of-turn). Emits     * [SttResult.Partial] for each whisper segment during transcription,     * then a single [SttResult.Final].     */    override suspend fun recognize(        audioStream: Flow<AudioCapturePipeline.AudioChunk>,        confidenceScorer: SttConfidenceScorer,    ): Flow<SttResult> = flow {        if (!isLoaded) {            emit(SttResult.Error(                reason = SttResult.Error.Reason.MODEL_CRASH,                message = "Whisper model not loaded",            ))            return@flow        }        // 1. Buffer audio chunks until VAD reports end-of-turn        //    (500 ms of silence, per sttConfig.silenceTimeoutMs).        val buffered = mutableListOf<AudioCapturePipeline.AudioChunk>()        var silenceStartMs: Long = 0L        var utteranceStarted = false        audioStream.collect { chunk ->            buffered.add(chunk)            if (chunk.hasVoice) {                utteranceStarted = true                silenceStartMs = 0L            } else if (utteranceStarted) {                if (silenceStartMs == 0L) silenceStartMs = chunk.timestampMs                val silenceMs = chunk.timestampMs - silenceStartMs                if (silenceMs >= sttConfig.silenceTimeoutMs) {                    // End of turn — transcribe the buffered audio.                    val result = transcribeBuffered(buffered, confidenceScorer)                    emit(result)                    buffered.clear()                    utteranceStarted = false                    silenceStartMs = 0L                    return@collect  // flow completes after one utterance                }            }            // Safety valve — if user talks for >30 s, force a final result.            val utteranceDurationMs = chunk.timestampMs - (buffered.firstOrNull()?.timestampMs ?: chunk.timestampMs)            if (utteranceDurationMs >= sttConfig.maxDurationMs) {                val result = transcribeBuffered(buffered, confidenceScorer)                emit(result)                buffered.clear()                utteranceStarted = false                return@collect            }        }        // Stream ended without silence trigger (mic released mid-utterance).        if (buffered.isNotEmpty() && utteranceStarted) {            emit(transcribeBuffered(buffered, confidenceScorer))        }    }    /**     * Transcribe a buffered utterance. Emits [SttResult.Partial]s as whisper     * produces segments, then a single [SttResult.Final].     */    private suspend fun transcribeBuffered(        chunks: List<AudioCapturePipeline.AudioChunk>,        scorer: SttConfidenceScorer,    ): SttResult = recognizeMutex.withLock {        cancelled.set(false)        val ptr = contextPtr.get()        if (ptr == 0L) {            return@withLock SttResult.Error(                reason = SttResult.Error.Reason.MODEL_CRASH,                message = "Whisper context freed mid-recognition",            )        }        // Flatten chunks into one ShortArray.        val samples = ShortArray(chunks.size * AudioCapturePipeline.CHUNK_SAMPLES)        chunks.forEachIndexed { i, chunk ->            System.arraycopy(chunk.samples, 0, samples, i * AudioCapturePipeline.CHUNK_SAMPLES, chunk.samples.size)        }        // Determine language: use sttConfig.languageHints first, or "auto".        val language = sttConfig.languageHints.firstOrNull()            ?.substringBefore('-')            ?: "auto"        // Confidence estimate from audio quality.        val confidence = scorer.scoreFromAudio(chunks)        val detectedLanguage = if (language == "auto") null else language        return@withLock try {            val finalText = WhisperJni.nativeFullStream(                contextPtr = ptr,                samples = samples,                language = language,                translate = config.translate,                speedUp = config.speedUp,                onPartial = { partialText ->                    // Forward partial to the flow's collector. We can't emit                    // from a callback directly, so we log it here — the                    // StreamingSttEngine collects partials via a separate                    // SharedFlow in a real wiring. For now, partial text is                    // included in the final result.                    Timber.tag(TAG).v("Whisper partial: $partialText")                },            )            if (cancelled.get()) {                Timber.tag(TAG).i("Recognition cancelled — emitting partial Final.")            }            SttResult.Final(                text = finalText,                language = detectedLanguage,                confidence = confidence,            )        } catch (t: UnsatisfiedLinkError) {            Timber.tag(TAG).e("UnsatisfiedLinkError during recognition", t)            SttResult.Error(                reason = SttResult.Error.Reason.MODEL_CRASH,                message = "Native method not linked: ${t.message}",            )        } catch (t: Throwable) {            Timber.tag(TAG).e("Recognition failed", t)            SttResult.Error(                reason = SttResult.Error.Reason.UNKNOWN,                message = t.message ?: "Unknown whisper error",            )        }    }    /** Abort in-progress recognition. Thread-safe. */    override suspend fun cancel() {        cancelled.set(true)        val ptr = contextPtr.get()        if (ptr != 0L) {            runCatching { WhisperJni.nativeStopRecognition(ptr) }        }    }    private companion object {        private const val TAG = "WhisperSttEngine"    }}